package com.example

import com.example.ExamQuestionHelper.QSpec

object MusicLiveExamHistoryMusiciansBank2 {
    private const val T = "ශ්‍රී ලාංකේය හා භාරතීය සංගීතවේදීන් හා සංගීත ඉතිහාසය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("භාරතීය සංගීත ඉතිහාසය ප්‍රධාන වශයෙන් කාල පරිච්ඡේද කීයකට බෙදා අධ්‍යයනය කෙරේද?", "3 කට (පුරාතන, මධ්‍යකාලීන හා නූතන)", "2 කට පමණි", "7 කට", "12 කට", "වෛදික හා පුරාණ යුගය, මධ්‍යකාලීන මෝගල් යුගය සහ නූතන යුගය ලෙස ප්‍රධාන යුග 3කි."),
        q("වෛදික යුගයේ සාම වේද ගායනාවලදී මුලින්ම භාවිත කරන ලද මූලික ස්වර තුන හඳුන්වන්නේ කුමන නම්වලින්ද?", "උදාත්ත, අනුදාත්ත සහ ස්වරිත", "ෂඩ්ජ, රිෂභ සහ ගාන්ධාර", "පංචම, ධෛවත සහ නිෂාද", "මන්ද්‍ර, මධ්‍ය සහ තාර", "උච්ච (උදාත්ත), පහළ (අනුදාත්ත) සහ මැද (ස්වරිත) යන ස්වර 3 සාම ගායනාවේ මුල විය."),
        q("මෝගල් අධිරාජ්‍ය සමයේදී උත්තර භාරතීය සංගීතය වඩාත් දියුණු වූයේ කුමන ස්ථාන කේන්ද්‍ර කරගෙනද?", "රාජ සභාවන් කේන්ද්‍ර කරගෙන", "පාසල් පන්ති කාමර තුළ", "නූතන ගුවන්විදුලි මැදිරි තුළ", "විදේශීය වෙළඳ නැව් තුළ", "අක්බර් වැනි රජවරුන්ගේ අනුග්‍රහය නිසා ශාස්ත්‍රීය රාග කලාව රාජ සභාවල උච්චත්වයට පත්විය."),
        q("උත්තර හා දක්ෂිණ භාරතීය සංගීත පද්ධති දෙක පැහැදිලිව වෙන් වී ගියේ කවර සියවසෙන් පසුවද?", "13 වන සියවසෙන් පසුව", "ක්‍රි.පූ. 5 වන සියවසේදී", "20 වන සියවසේ අගදී", "21 වන සියවසේදී", "මධ්‍යකාලීන මුස්ලිම් හා පර්සියානු ආභාසය උතුරු ඉන්දියාවට ලැබීමත් සමඟ පද්ධති දෙක වෙන් විය."),
        q("'සංගීත පාරිජාත' නැමැති 17 වන සියවසේ ප්‍රසිද්ධ සංගීත ග්‍රන්ථය රචනා කළ පඬිවරයා කවුද?", "අහෝබල පඬිතුමා", "භරතමුනි", "ශාර්ංගදේව", "ජයදේව", "වීණාවේ තන්තු දිග අනුව ස්වර 12හි ස්ථාන මුල් වරට විද්‍යාත්මකව දැක්වූයේ අහෝබල පඬිතුමාය."),
        q("තන්තුවක දිග බෙදා ස්වර ස්ථාන නිශ්චය කළ ප්‍රථම භාරතීය ග්‍රන්ථය ලෙස සැලකෙන්නේ කුමක්ද?", "සංගීත පාරිජාත", "නාට්‍ය ශාස්ත්‍රය", "ගීත ගෝවින්දය", "සාම වේදය", "පණ්ඩිත් අහෝබල විසින් වීණා තන්තුවේ කම්පන දිග ඇසුරෙන් ස්වර ස්ථාන ගණනය කළේය."),
        q("'රාග තරංගිනී' කෘතිය රචනා කර මේල හෙවත් ථාට සංකල්පයට මූලික අඩිතාලම දැමුවේ කවුද?", "ලෝචන කවිතුමා", "තාන්සේන්", "අමීර් ඛුස්රෝ", "පිලිප්පු සිංඤෝ", "ලෝචන කවියා රාග තරංගිනී ග්‍රන්ථයේ මූලික සංස්ථාන 12ක් පිළිබඳව සඳහන් කළේය."),
        q("භාරතීය සංගීතයට 'ඛ්‍යාල්' (Khayal) ගායන ශෛලිය ප්‍රචලිත කිරීමට දායක වූ 18 වන සියවසේ සංගීතඥයා කවුද?", "සදාරංග (නියාමත් ඛාන්) සහ අදාරංග", "භරතමුනි සහ මතංගමුනි", "ජෝන් ද සිල්වා සහ සී. දොන් බස්තියන්", "පිලිප්පු සිංඤෝ සහ චාල්ස් ගුණසිංහ", "මුහම්මද් ෂා රංගීලේ රජුගේ සභාවේ සදාරංග හා අදාරංග බොහෝ ඛ්‍යාල් බන්දිශ් රචනා කළහ."),
        q("'භාත්ඛණ්ඩේ' හා 'පලුස්කර්' යන දෙදෙනා භාරතීය සංගීතයට සිදු කළ පොදු මහා මෙහෙය කුමක්ද?", "රාජ සභාවලට සීමා වූ සංගීතය පොදු අධ්‍යාපනයට හා ස්වරලිපිගත කිරීමට ගෙන ඒම", "තබ්ලාව වාදනය තහනම් කිරීම", "සංගීත ග්‍රන්ථ සියල්ල විනාශ කිරීම", "බටහිර පොප් ගීත පමණක් ප්‍රචලිත කිරීම", "20 වන සියවසේ මුලදී ඉන්දීය සංගීත පුනරුදයට එතුමන්ලා පදනම දැමූහ."),
        q("ශ්‍රී ලංකාවේ ප්‍රථම ග්‍රැමෆෝන් ගීත තැටි පටිගත වූයේ කවර සියවසේද?", "20 වන සියවසේ මුල (1903 පමණ)", "16 වන සියවසේ", "18 වන සියවසේ", "21 වන සියවසේ", "1903 සිට නූර්ති හා කවි ගායනා මුල්ම ග්‍රැමෆෝන් තැටිවල පටිගත කෙරිණි."),
        q("1925 දී ශ්‍රී ලංකාවේ (ලංකාවේ) ගුවන්විදුලි සේවය ආරම්භ වීමෙන් සංගීතයට ලැබුණු වාසිය කුමක්ද?", "රට පුරා සිටින අසන්නන්ට එකවර ගීත හා සංගීත වැඩසටහන් ශ්‍රවණයට ලැබීම", "වාද්‍ය භාණ්ඩ අලෙවිය නතර වීම", "නාඩගම් ශාලා බිඳ වැටීම පමණක්", "ගායකයන්ගේ හඬ පටිගත කිරීම නැවතීම", "ලංකා ගුවන්විදුලිය මෙරට සරල ගී, නාට්‍ය ගී හා ශාස්ත්‍රීය සංගීතයේ ප්‍රධාන තවාන් බිම විය."),
        q("'රේඩියෝ සිලෝන්' යුගයේදී මෙරට සංගීතය හැඩගැස්වීමට දායක වූ ප්‍රධාන සංගීත පර්යේෂණ හා වාද්‍ය මණ්ඩල ප්‍රධානීන් අතරින් කෙනෙකු නම් කරන්න.", "පණ්ඩිත් ඩබ්ලිව්. ඩී. අමරදේව", "මියාන් තාන්සේන්", "භරතමුනි පඬිතුමා", "වෙන්කටමුඛී විද්වතා", "ගුවන්විදුලි වාද්‍ය මණ්ඩලය හරහා උසස් සරල ගී සහ ශාස්ත්‍රීය සංගීතය ගොඩනැගිණි."),
        q("ශ්‍රී ලංකා ගුවන්විදුලි සංස්ථාවේ ගීත ශ්‍රේණිගත කිරීමේදී (Audition) 'විශිෂ්ට ශ්‍රේණිය' හිමිවන්නේ කුමන ශිල්පීන්ටද?", "ඉහළ ගායන/වාදන ප්‍රමිතිය හා ස්වර-තාල නිවැරදිතාව ඇති ශිල්පීන්ට", "මුල් වරට අයදුම් කරන සියලු දෙනාට", "ඉංග්‍රීසි ගීත පමණක් ගයන අයට", "වාද්‍ය භාණ්ඩ අලෙවිකරුවන්ට", "A/විශිෂ්ට ශ්‍රේණියේ ශිල්පීන් ස්වර, තාල, උච්චාරණය හා භාව ප්‍රකාශනයෙන් විශිෂ්ටත්වය පෙන්විය යුතුය."),
        q("දේශීය ගුවන්විදුලියේ ආරම්භක අවධියේදී 'සුනිල් ශාන්තයන්' රේඩියෝ සිලෝන් වෙතින් ඉවත් වීමට හේතු වූ මතභේදය කුමක්ද?", "ඉන්දීය පරීක්ෂකවරයෙකු (රතන්ජංකර්) හරහා ගායකයන් වර්ගීකරණය කිරීමට විරුද්ධ වීම", "වැටුප් වැඩි කරන ලෙස ඉල්ලීම පමණක්", "නාඩගම් රඟපෑමට කාලය මදි වීම", "සිතාර් වාදනය කිරීමට බැරි වීම", "1952 දී රතන්ජංකර් පරීක්ෂණයට විරෝධය පා සුනිල් ශාන්ත ගුවන්විදුලියෙන් ඉවත් විය."),
        q("1952 දී ලංකාවේ ගුවන්විදුලි ගායකයන් පරීක්ෂා කර ශ්‍රේණිගත කිරීම සඳහා ඉන්දියාවෙන් ගෙන්වූ සංගීත විද්වතා කවුද?", "පණ්ඩිත් ශ්‍රී ක්‍රිෂ්ණ නාරායන් රතන්ජංකර්", "අමීර් ඛුස්රෝ", "පණ්ඩිත් රවි ශංකර්", "මියාන් තාන්සේන්", "ලක්නව්හි භාත්ඛණ්ඩේ ආයතනයේ විදුහල්පති වූ පණ්ඩිත් රතන්ජංකර් මහතා මෙහි පැමිණියේය."),
        q("පණ්ඩිත් රතන්ජංකර්ගේ ගුවන්විදුලි සංගීත පරීක්ෂණයෙන් ඒ (A) ශ්‍රේණියේ 'සුපර් ග්‍රේඩ්' ගෞරවය ලද ලාංකිකයා කවුද?", "පණ්ඩිත් ඩබ්ලිව්. ඩී. අමරදේව (ඇල්බට් පෙරේරා)", "පිලිප්පු සිංඤෝ", "වොලී බැස්ටියන්", "සී. දොන් බස්තියන්", "එවකට ඇල්බට් පෙරේරා ලෙස පෙනී සිටි අමරදේවයන් ඉහළම දක්ෂතා පෙන්වා ශිෂ්‍යත්ව ලබා භාත්ඛණ්ඩේ ගියේය."),
        q("පණ්ඩිත් අමරදේවයන්ගේ සංගීත ශෛලිය හඳුන්වනු ලබන පොදු විශේෂත්වය කුමක්ද?", "සිංහල ජන ගී නාද හා උත්තර භාරතීය රාගධාරී ශිල්පය මුසු කිරීම", "බටහිර රොක් සංගීතය පමණක් වැයීම", "හින්දි ගී තනු එලෙසම ගැයීම", "බෙර පද පමණක් ගායනය", "ජන නාද ආත්මය රාගධාරී ශාස්ත්‍රීය ශිල්පයෙන් ඔපමට්ටම් කිරීම අමරදේව සංගීතයේ හරයයි."),
        q("මහගම සේකර හා ඩබ්ලිව්. ඩී. අමරදේව සුසංයෝගයෙන් බිහිවූ 'මධුවන්ති' ගීත අතර ප්‍රසිද්ධ ගීතයක් කුමක්ද?", "ඈත කඳුකර හිමව් අරණේ / රත්නදීප ජන්ම භූමි", "රොලීනා කුමාරි", "දන්නෝ බුදුන්ගේ", "කඩවුණු පොරොන්දුව", "රත්නදීප ජන්ම භූමි, සන්නාලියනේ, මලින් මලේ වැනි ගීත මෙම සුසංයෝගයේ මහඟු ඵලයන්ය."),
        q("සිංහල සංගීතයට 'ශාස්ත්‍රීය ගැඹුරක්' එක් කළ ප්‍රවීණ සිතාර් වාදකයෙකු හා ගුරුවරයෙකු වූයේ කවුද?", "ප්‍රේමදාස අතුකෝරල / පී. වී. නන්දසිරි / නවරත්න ගමගේ", "පිලිප්පු සිංඤෝ", "සී. දොන් බස්තියන්", "රොමුලස් ද සිල්වා", "ප්‍රේමදාස අතුකෝරල හා පී. වී. නන්දසිරි වැනි සංගීතඥයන් මෙරට සිතාර් හා රාගධාරී පරපුර පෝෂණය කළහ."),
        q("සිංහල සරල ගීත ක්ෂේත්‍රයේ විශාරද 'එඩ්වඩ් ජයකොඩි' සහ 'සමන්තා පෙරේරා / චරිතා ප්‍රියදර්ශනී' වැන්නන් ප්‍රකට වන්නේ කුමකටද?", "ප්‍රාසාංගික හා භාවපූර්ණ සරල ගී ගායනයට", "නාඩගම් පොත් රචනයට", "පැරණි හොරණෑ තැනීමට", "සංස්කෘත ශ්ලෝක ලිවීමට", "සමකාලීන ප්‍රබුද්ධ සරල ගීත හා මාරම්බරී වැනි ප්‍රසංග හරහා සරල ගීය ඉදිරියට ගෙන ගියහ."),
        q("ශ්‍රී ලංකාවේ 'පූජා සංගීතය' හා කතෝලික ගීතිකා සිංහල ජන ආරට ගෙන ඒමට පුරෝගාමී වූ කිවිඳුන් කවුද?", "මර්සලීන් ජයකොඩි පියතුමා", "සී. දොන් බස්තියන්", "පිලිප්පු සිංඤෝ", "ජෝන් ද සිල්වා", "මර්සලීන් ජයකොඩි පියතුමා කැරොල් ගීත හා චිත්‍රපට ගීතවලට දේශීය හුරුව හා හෙළ බස ලබා දුන්නේය."),
        q("මර්සලීන් ජයකොඩි පියතුමා පද රචනා කළ අතිශය ජනප්‍රිය දේශීය නත්තල් ගීතයක් හෝ චිත්‍රපට ගීතයක් වන්නේ කුමක්ද?", "සීනු හඬින් ලොව පිබිදෙනවා / ඕලු නෙළුම් නෙරිය රඟාලා", "දන්නෝ බුදුන්ගේ", "ප්‍රේමයෙන් මන රංජිත වේ", "ගල් ලෙන බිඳලා", "රේඛාව චිත්‍රපටයේ ගීත මෙන්ම සීනු හඬින් ලොව පිබිදෙනවා වැනි ගීත ජයකොඩි පියතුමාගේ නිර්මාණය."),
        q("සිංහල සරල ගීතයේ භාවාත්මක කාන්තා හඬ සනිටුහන් කළ 'මාලිනී බුලත්සිංහල' ගැයූ සුප්‍රකට ගීතයක් කුමක්ද?", "මා හඬනා කඳුළු ගලා", "දන්නෝ බුදුන්ගේ", "ලප නොමවන් සඳ සේ", "එන්ඩද මැණිකේ", "විශාරද මාලිනී බුලත්සිංහල භාවපූර්ණ හා ශාස්ත්‍රීය ආභාසය ඇති සරල ගී ගායනයෙන් විශිෂ්ට විය."),
        q("ශ්‍රී ලංකාවේ ගීත නාටක, මුද්‍රා නාට්‍ය හා පර්යේෂණ කලාව පෝෂණය කළ 'චිත්‍රසේන - වජිරා' පරපුර සමඟ වැඩ කළ සංගීතඥයෙකු කවුද?", "පණ්ඩිත් අමරදේව / සෝමදාස ඇල්විටිගල", "මියාන් තාන්සේන්", "අමීර් ඛුස්රෝ", "පිලිප්පු සිංඤෝ", "කරදිය සහ නල දමයන්ති වැනි මුද්‍රා නාට්‍යවල සංගීතය පණ්ඩිත් අමරදේව ආදීන් නිර්මාණය කළහ."),
        q("පණ්ඩිත් අමරදේවයන් සංගීතය සැපයූ චිත්‍රසේනයන්ගේ සුප්‍රකට මුද්‍රා නාට්‍යය කුමක්ද?", "කරදිය (1961)", "රොලීනා (1877)", "ඇහැලේපොළ නාඩගම", "කඩවුණු පොරොන්දුව", "ධීවර ජීවිතය පසුබිම් කරගත් කරදිය මුද්‍රා නාට්‍යයේ සංගීතය ලාංකේය මුද්‍රා නාට්‍ය කලාවේ මුදුන්මල්කඩකි."),
        q("ලංකාවේ මුල්ම දේශීය ගීත පටිගත කිරීමේ හා වාද්‍ය මණ්ඩල මෙහෙයවීමේදී වැදගත් වූ 'බී. එස්. පෙරේරා' කවර භාණ්ඩයක වාදකයෙකුද?", "සර්පිනාව (හාමෝනියම්) හා සංගීත අධ්‍යක්ෂණය", "සැක්සෆෝනය පමණක්", "තම්මැට්ටම පමණක්", "කොතෝ වීණාව", "ග්‍රැමෆෝන් හා මුල් චිත්‍රපට යුගයේ හාමෝනියම් වාදකයෙකු හා තනු නිර්මාපකයෙකු ලෙස එතුමා ප්‍රසිද්ධය."),
        q("ශ්‍රී ලංකාවේ සංගීත අධ්‍යාපනය වෙනුවෙන් පළමු පෙළපොත් හා විෂය නිර්දේශ සකස් කිරීමේදී මූලික වූ ආයතනය කුමක්ද?", "ජාතික අධ්‍යාපන ආයතනය (NIE) හා අධ්‍යාපන දෙපාර්තමේන්තුව", "ටවර් හෝල් ශාලාව පමණක්", "එච්. එම්. වී. සමාගම", "බොම්බාය පාර්සි සංගමය", "පාසල් සිසුන් සඳහා ක්‍රමවත් පෙරදිග සංගීත විෂය මාලා ජාතික අධ්‍යාපන ආයතනය මගින් සකසයි."),
        q("භාරතීය ශාස්ත්‍රීය සංගීතයේ 'ධ්‍රැපද්' ගායන ශෛලිය බිහිවූයේ සහ එය වැඩිදියුණු කළේ කවුරුන් අතින්ද?", "ග්වාලියර්හි රාජා මාන්සිං තෝමර්", "පණ්ඩිත් භාත්ඛණ්ඩේ", "ආනන්ද සමරකෝන්", "රබීන්ද්‍රනාත් තාගෝර්", "15 වන සියවසේ ග්වාලියර්හි රාජා මාන්සිං තෝමර් ධ්‍රැපද් කලාවට විශාල රාජ්‍ය අනුග්‍රහයක් ලබා දුන්නේය."),
        q("රාජා මාන්සිං තෝමර් විසින් සංගීත ශාස්ත්‍රය පිළිබඳව සම්පාදනය කරන ලද ප්‍රසිද්ධ ග්‍රන්ථය කුමක්ද?", "මාන් කුතූහල් (Man Kutuhal)", "නාට්‍ය ශාස්ත්‍රය", "ගීත ගෝවින්දය", "සංගීත රත්නාකරය", "එවකට පැවති රාග හා ගායන ක්‍රම රැස්කර මාන් කුතූහල් නම් හින්දි කෘතිය සකස් කෙරිණි."),
        q("ධ්‍රැපද් ගායන සම්ප්‍රදායේ කොටස් හතර නිවැරදිව දැක්වෙන පිළිවෙළ කුමක්ද?", "ස්ථායි, අන්තරා, සංචාරී, ආභෝග", "ආලාප, තාන, ධාල, සම", "මුඛඩා, පල්ලවි, චරණම්, මංගලම්", "විලම්බ, මධ්‍ය, දෘත, අතිදෘත", "සම්පූර්ණ ධ්‍රැපද් ගීතයක ස්ථායි, අන්තරා, සංචාරී සහ ආභෝග යන අංග 4 අඩංගු වේ."),
        q("වර්තමානයේ ඉතා ජනප්‍රිය උත්තර භාරතීය 'ඛ්‍යාල්' (Khayal) ගීතයක ඇති ප්‍රධාන කොටස් දෙක කුමක්ද?", "ස්ථායි සහ අන්තරා", "පල්ලවි සහ අනුපල්ලවි", "සංචාරී සහ ආභෝග පමණක්", "ඉන්නිස සහ සින්දුව", "ඛ්‍යාල් ගීත සාමාන්‍යයෙන් ස්ථායි (පළමු කොටස) සහ අන්තරා (දෙවන උච්ච කොටස) ලෙස කොටස් 2කින් යුක්තය."),
        q("විශාල ඛ්‍යාල් (Bada Khayal) ගායනා කරනු ලබන්නේ කවර ලයකට අනුවද?", "විලම්බ ලයට", "අති දෘත ලයට", "ලය නොමැතිව", "සමාන බයිලා ලයට", "බඩා ඛ්‍යාල් ඉතා සෙමින් ගැඹුරු විලම්බ ලයෙන් ආරම්භ කර පසුව චෝටා ඛ්‍යාල් වෙත යොමු වේ."),
        q("කුඩා ඛ්‍යාල් (Chota Khayal) ගායනා කරනු ලබන්නේ කවර ලයකට අනුවද?", "මධ්‍ය හෝ දෘත ලයට", "අති විලම්බ ලයට පමණක්", "තාලයකින් තොරව", "මන්ද්‍ර ලයට", "චෝටා ඛ්‍යාල් මධ්‍ය ලයෙන් හෝ වේගවත් දෘත ලයෙන් ත්‍රිතාල, ඒක්තාල වැනි තාලවලට ගැයේ."),
        q("'ධමාර්' (Dhamar) ගායන ශෛලිය සාමාන්‍යයෙන් ගායනා කරනු ලබන්නේ කවර ඉන්දීය උත්සවයක් හා සම්බන්ධවද?", "හෝලි (Holi) වසන්ත උත්සවය", "දීපවාලි උත්සවය පමණක්", "නත්තල් උත්සවය", "වෙසක් උත්සවය", "ශ්‍රී ක්‍රිෂ්ණා හා ගෝපිකාවන්ගේ හෝලි වර්ණ උත්සවය වර්ණනා කරමින් මාත්‍රා 14 ධමාර් තාලයට ගැයේ."),
        q("'ඨුම්රි' (Thumri) ගායන ශෛලිය ශාස්ත්‍රීය සංගීතයේ කුමන ගණයට අයත් වේද?", "අර්ධ ශාස්ත්‍රීය (Semi-classical / උපශාස්ත්‍රීය) ගණයට", "පූර්ණ බටහිර ඔපෙරා ගණයට", "දේශීය ගැමි කවි ගණයට", "නාඩගම් ගණයට", "ශෘංගාර රසය ප්‍රධාන කරගත් රාග නීති මදක් ලිහිල් කර ගැයෙන උපශාස්ත්‍රීය අංගයක් ඨුම්රි වේ."),
        q("ඨුම්රි ගායනා සඳහා බහුලව යොදාගන්නා මෘදු තාල වර්ග මොනවාද?", "දීප්චන්දි, ඛහර්වා සහ දාද්‍රා", "චෞතාල සහ ධමාර්", "සූල්තාල සහ බ්‍රහ්මතාල", "මත්ත තාලය", "මාත්‍රා 14 දීප්චන්දි හෙවත් චාන්චර් තාලය ඨුම්රි සඳහා සුවිශේෂී වේ."),
        q("සිංහල සංගීත වංශකතාවේ 'ගසල්' (Ghazal) ගායන ශෛලියට සම්භවය ලැබුණේ කවර සාහිත්‍යයෙන්ද?", "පර්සියානු හා උර්දු කාව්‍ය සාහිත්‍යයෙන්", "සිංහල ජන කවියෙන්", "ලතින් කාව්‍යයෙන්", "ජපන් හයිකු කවියෙන්", "ආදරය හා විරහව ගැන ලියැවුණු උර්දු කාව්‍ය සංගීතයට නගා ගැයීම ගසල් නම් වේ."),
        q("භාරතීය ගසල් සංගීතයේ සුප්‍රකට ගායකයන් අතර ලොව පුරා ප්‍රචලිත වූ 'මෙහෙදි හසන්' සහ 'ජග්ජිත් සිං' හඳුන්වන්නේ කුමන නමින්ද?", "ගසල් සම්‍රාට් / ගසල් මහා ගායකයන් ලෙස", "ධ්‍රැපද් පුරෝගාමීන් ලෙස", "වන්නම් රචකයන් ලෙස", "මද්දල වාදකයන් ලෙස", "ගසල් සංගීතය ඉන්දියාවේ හා පකිස්ථානයේ මෙන්ම ලංකාවේද ජනප්‍රිය කිරීමට ඔවුහු දායක වූහ."),
        q("සිංහල ගීත කලාවේ 'විරහ ගීත' හා 'උපශාස්ත්‍රීය' ලක්ෂණ ඇතුළත් සරල ගී නිර්මාණයේදී බලපෑම් කළ භාරතීය ශෛලිය කුමක්ද?", "ගසල් හා ඨුම්රි ශෛලීන්", "සාම වේද ශෛලිය පමණක්", "කර්ණාටක මෘදංග තනි වාදනය", "පංජාබ් බංග්‍රා නැටුම් පමණක්", "මිල්ටන් මල්ලවාරච්චි, අමරදේව ආදීන්ගේ ඇතැම් භාවපූර්ණ ගීතවලට ගසල් හා ඨුම්රි ආභාසය ලැබිණි."),
        q("භාරතයේ විසූ ශ්‍රේෂ්ඨ කවි හා සංගීතඥ 'කබීර්' සහ 'මීරාබායි' ප්‍රසිද්ධ වන්නේ කුමන භක්ති ගීත විශේෂය සඳහාද?", "භජන් ගීත (දෝහා සහ පද)", "බටහිර සිම්ෆනි", "සිංහල සීපද", "පෘතුගීසි බයිලා", "දෙවියන් කෙරෙහි භක්තියෙන් ගැයෙන සරල රාගාශ්‍රිත භජන් ගී ඔවුන් බිහි කළහ."),
        q("'භාත්ඛණ්ඩේ ස්වරලිපි ක්‍රමය' හා 'පලුස්කර් ස්වරලිපි ක්‍රමය' අතරින් ශ්‍රී ලංකාවේ පාසල්වල බහුලව භාවිත කරන්නේ කුමක්ද?", "භාත්ඛණ්ඩේ ස්වරලිපි ක්‍රමය", "පලුස්කර් ස්වරලිපි ක්‍රමය", "රෝම ඉලක්කම් ක්‍රමය", "තමිල් වට්ටෙළුත්තු ක්‍රමය", "පහසුවෙන් ලිවිය හැකි සංකේත නිසා භාත්ඛණ්ඩේ ක්‍රමය මෙරට අධ්‍යාපනයේ සම්මතය වී ඇත."),
        q("පලුස්කර් ස්වරලිපි ක්‍රමය තුළ 'එක් මාත්‍රාවක්' හා 'අඩ මාත්‍රාවක්' දැක්වීමට යොදාගන්නේ කුමන ආකාරයේ සලකුණුද?", "ස්වරයට පහළින් විශේෂ සංඛ්‍යා හා ඉර-තරු සංකේත", "ස්වරය වටා කොටු ඇඳීම", "වර්ණ කෝඩ් යෙදීම", "කතිර පමණක් යෙදීම", "පලුස්කර් ක්‍රමයේදී භාත්ඛණ්ඩේ මෙන් නොව එක් එක් මාත්‍රා අගය සඳහා වෙනස් සංකේත පහළින් යොදයි."),
        q("භාරතීය සංගීතයේ 'අනාදිමත් කාලයක සිට පැවත එන' ගුරු-ශිෂ්‍ය පරම්පරා ඉගැන්වීමේ ක්‍රමය හඳුන්වන්නේ කුමන නමින්ද?", "ගුරුකුල සම්ප්‍රදාය (Guru-Shishya Parampara)", "අන්තර්ජාල අධ්‍යාපනය", "සංයුක්ත තැටි අධ්‍යාපනය", "විභාග පුහුණු කඳවුර", "ශිෂ්‍යයා ගුරුවරයා සෙවණේ වසර ගණනාවක් නැවතී ප්‍රායෝගිකව ශිල්ප උගන්නා ක්‍රමය මෙයයි."),
        q("ශ්‍රී ලංකාවේ 'ජාතික ගීය' ප්‍රථම වරට නිදහස් දින උත්සවයකදී නිල වශයෙන් ගායනා කරන ලද්දේ කවර වර්ෂයේදීද?", "1952 දී", "1940 දී", "1972 දී", "1980 දී", "1951 දී කැබිනට් මණ්ඩලය විසින් සම්මත කිරීමෙන් පසු 1952 නිදහස් උත්සවයේදී නිල වශයෙන් ගැයිණි."),
        q("ශ්‍රී ලංකාවේ ජාතික ගීය නිර්මාණය කරන විට ආනන්ද සමරකෝන් මහතා එය මුලින්ම යොමු කළේ කවුරුන් වෙනුවෙන්ද?", "ගාල්ලේ මහින්ද විද්‍යාලයේ සිසුන් වෙනුවෙන්", "බොම්බායේ නාට්‍ය ශාලාවකට", "ලන්ඩන් රජු වෙනුවෙන්", "ග්‍රැමෆෝන් සමාගමට පමණක්", "මහින්ද විද්‍යාලයේ සිසුන් තුළ දේශාභිමානය ඇති කිරීම සඳහා ප්‍රභාත ගීයක් ලෙස නිර්මාණය විය."),
        q("ශ්‍රී ලංකා ජාතික ගීය ගායනා කිරීමේදී පවත්වා ගත යුතු නිවැරදි ආචාරධර්මය කුමක්ද?", "සීරුවෙන් සිටගෙන නිවැරදි තනුවට හා වචනවලට ගෞරවයෙන් ගැයීම", "අසුන්ගෙන කතා කරමින් ගැයීම", "තනුව වේගවත් කර නැටීම", "අතරමැද නවතා අත්පොළසන් දීම", "ජාතික ගීය සීරුවෙන් සිට ගෞරවාන්විතව එකම සම්මත තාලයට හා ස්වරයට ගැයිය යුතුය."),
        q("සිංහල සංගීතයේ 'මුල් යුගයේ සිනමා ගීත' බොහොමයක තනු පැමිණියේ කුමන ප්‍රභවයකින්ද?", "දකුණු හා උතුරු ඉන්දීය චිත්‍රපට තනුවලින්", "ජපන් ජන ගී වලින්", "අප්‍රිකානු ගෝත්‍රික ගී වලින්", "රුසියානු බැලේ සංගීතයෙන්", "1947-1955 කාලයේ බොහෝ සිංහල චිත්‍රපට ඉන්දියාවේ රූගත කළ බැවින් හින්දි/දෙමළ තනු එක්විය."),
        q("1956 න් පසු සිංහල චිත්‍රපට සංගීතයේ ස්වතන්ත්‍රභාවය ඇති කිරීමට 'සන්දේශය', 'කුරුලු බැද්ද', 'ගම්පෙරළිය' දැක්වූ දායකත්වය කුමක්ද?", "දේශීය හා ශාස්ත්‍රීය නව නිර්මාණ බිහි වීම", "ඉංග්‍රීසි පමණක් භාවිත වීම", "ගීත සියල්ල ඉවත් වීම", "බෙර වාදනය තහනම් වීම", "සුනිල් ශාන්ත, රූපසිංහ, අමරදේව හා කේමදාස වැනි ශිල්පීන් සිනමා සංගීතය දේශීයකරණය කළහ."),
        q("ශ්‍රී ලංකාවේ 'ගීත සාහිත්‍යය' හා සංගීතය අතර අන්තර් සම්බන්ධය ශක්තිමත් කළ කලාකරුවන් හඳුන්වන්නේ කුමන නමකින්ද?", "වාග්ගේයකාරවරුන් (හෝ ගීත නිබන්ධක හා තනු නිර්මාපකයන්)", "වාද්‍ය භාණ්ඩ අලුත්වැඩියාකරුවන්", "නාට්‍ය තිර අඳින්නන්", "වෙස්මුහුණු කැටයම්කරුවන්", "ගීත පද හා තනු යන දෙකම නිර්මාණය කිරීමේ හැකියාව ඇති විශිෂ්ටයෝ වාග්ගේයකාරවරු නම් වෙති."),
        q("දේශීය සංගීතඥයන් අතර 'පද රචනය සහ සංගීත නිර්මාණය' යන දෙකම කළ ශ්‍රී ලාංකිකයන් දෙදෙනෙකු නම් කරන්න.", "ආනන්ද සමරකෝන් සහ සුනිල් ශාන්ත", "සී. දොන් බස්තියන් සහ රවි ශංකර්", "මියාන් තාන්සේන් සහ බීතෝවන්", "අමීර් ඛුස්රෝ සහ කේමදාස", "ආනන්ද සමරකෝන් හා සුනිල් ශාන්ත තම ගීතවල පදමාලාව හා තනුව බොහෝ විට තමන්ම නිමවූහ."),
        q("පණ්ඩිත් අමරදේවයන්ගේ හඬ පිළිබඳව විචාරකයන් දක්වන විශේෂ ගුණාංගය කුමක්ද?", "හෙළ ශූරතාව, ගාම්භීරත්වය සහ භාවපූර්ණ ස්වර සුසංයෝගය", "ඉතා වේගවත් කතා විලාසය", "බටහිර යාන්ත්‍රික හඬ", "තාල රහිත ගායනය", "අමරදේවයන්ගේ හඬෙහි පැහැදිලි වචන උච්චාරණය හා ශාස්ත්‍රීය මෘදු ගමක අලංකාර පිහිටියේය."),
        q("සිංහල ගුවන්විදුලි සංගීතයේ 'බෞද්ධ ගීත' හා 'දේශාභිමානී ගීත' වර්ධනයට විශාල සේවයක් කළේ කවුද?", "ඩබ්ලිව්. ඩී. අමරදේව, මොහිදීන් බෙග් හා නන්දා මාලිනී", "තාන්සේන් හා බෛජු බව්රා", "මෝසාර්ට් හා බීතෝවන්", "වෙන්කටමුඛී හා අහෝබල", "වෙසක් හා පොසොන් සමයේදී බිහිවූ බෞද්ධ ගීත සිංහල සංගීත උරුමයේ වැදගත් කොටසකි."),
        q("'සප්ත කන්‍යා' හෝ 'මිහිමඬලේ අඳුරු කුසේ' වැනි අර්ථපූර්ණ ගීත නිර්මාණය කළ ප්‍රවීණ සංගීතඥ 'එච්. එම්. ජයවර්ධන' ප්‍රකට වන්නේ කුමකටද?", "ශෝකී හා සංවේදී මානුෂීය සරල ගී තනු නිර්මාණයට", "වේගවත් කපිරිඤ්ඤා ගීතවලට", "තම්මැට්ටම් වාදනයට", "සංස්කෘත නාට්‍ය රචනයට", "ප්‍රේමකීර්ති ද අල්විස්, සුනිල් ආරියරත්න වැන්නවුන්ගේ ගීතවලට එතුමා අමරණීය තනු සැපයීය."),
        q("සිංහල ගීත ක්ෂේත්‍රයේ විශිෂ්ට තනු නිර්මාපකයෙකු වූ 'ස්ටැන්ලි පීරිස්' හා 'ෆෝචූන්ස්' වාදක කණ්ඩායම ප්‍රසිද්ධ වන්නේ කුමකටද?", "ප්‍රසංග වේදිකාව හා පටිගත කිරීමේ වාද්‍ය සංයෝජනයට", "නාඩගම් පොතේගුරු භූමිකාවට", "පැරණි ගැටබෙර නිෂ්පාදනයට", "ගමේ සොකරි කවි ගායනයට", "1970-90 දශකවල සරල ගී හා කැසට් යුගයේ සංගීත සංයෝජනයට එතුමා විශාල දායකත්වයක් දැක්වීය."),
        q("1970 දශකයේ අගභාගයේ සිට ශ්‍රී ලංකාවේ 'කැසට් පට' (Cassette Era) පැමිණීම සංගීතයට බලපෑවේ කෙසේද?", "ගායක ගායිකාවන්ට ස්වාධීන ගීත ඇල්බම බිහිකිරීමට මග පෑදීම", "සියලු ප්‍රසංග නතර වීම", "සංගීතය පාසල්වලින් ඉවත් කිරීම", "වාද්‍ය භාණ්ඩ අහෝසි වීම", "ගුවන්විදුලියට අමතරව ගායකයන්ට පුද්ගලික ගීත එකතු රසිකයන් අතට පත් කිරීමට ඉඩ ලැබුණි."),
        q("'සඳ එළිය ගලා එන' හෝ 'ගඟ අද්දර' වැනි ගීතවලට තනු නිමවූ නිමල් මෙන්ඩිස් සහ සරත් දසනායක ප්‍රකට වන්නේ කවර මාධ්‍යයකද?", "චිත්‍රපට හා සරල ගී සංගීත අධ්‍යක්ෂණය", "කෝලම් බෙර වාදනය", "පල්ලියේ පයිප් ඕගන් වාදනය", "රජ සභා වන්නම් රචනය", "සරත් දසනායක හා නිමල් මෙන්ඩිස් සිංහල සිනමා සංගීතයට මිහිරි ජනප්‍රිය තනු රැසක් තිළිණ කළහ."),
        q("සිංහල ගීත කලාවේ 'මහාචාර්ය සුනිල් ආරියරත්න' හඳුන්වනු ලබන්නේ කුමන ප්‍රධාන දායකත්වය සඳහාද?", "ගී පද රචනය හා සංගීත ශාස්ත්‍රීය පර්යේෂණ", "තබ්ලා නිෂ්පාදනය", "වයලීන අලුත්වැඩියාව", "නාඩගම් අණබෙර ගැසීම", "උසස් සාහිත්‍යමය ගීත රැසක් ලියූ එතුමා නූර්ති, නාඩගම් හා ග්‍රැමෆෝන් ගී පිළිබඳ ග්‍රන්ථද රචනා කළේය."),
        q("ශ්‍රී ලංකාවේ ප්‍රථම සංගීත උපාධිධාරී පරපුර බිහිකිරීමට පසුබිම සැකසුණු විශ්වවිද්‍යාල අධ්‍යාපන වෙනස්කම කුමක්ද?", "සෞන්දර්ය අධ්‍යයන ආයතනය කැලණිය හා පසුව සෞන්දර්ය කලා විශ්වවිද්‍යාලය බවට පත්වීම", "වෛද්‍ය විද්‍යාලයට සංගීතය යෙදීම", "සියලු සංගීත පාසල් වසා දැමීම", "ඉංග්‍රීසි පමණක් ඉගැන්වීම", "සෞන්දර්ය කලා විශ්වවිද්‍යාලය පිහිටුවීමෙන් පසු සංගීතය පිළිබඳ විද්‍යාර්ථීන් හා පර්යේෂකයෝ බිහිවූහ."),
        q("'ලංකා ගාන්ධර්ව සභාව' ආරම්භයේදී මෙරට සංගීත හා නර්තන අධ්‍යාපනයට ඉටු කළ සේවාව කුමක්ද?", "ප්‍රාදේශීය පරීක්ෂණ පවත්වා සංගීත සහතික පිරිනැමීම", "චිත්‍රපට ශාලා ඉදිකිරීම", "ගුවන්විදුලි යන්ත්‍ර විකිණීම", "බෙර තහනම් කිරීම", "රට පුරා විභාග මධ්‍යස්ථාන පිහිටුවා විධිමත් සංගීත ප්‍රවීණතා ඇගයීම් ලබා දුන්නේය."),
        q("උත්තර භාරතීය ශාස්ත්‍රීය සංගීතයේ 'ප්‍රායෝගික හා න්‍යායාත්මක' විභාග පවත්වන භාත්ඛණ්ඩේ සංගීත විද්‍යාපීඨය මගින් පිරිනමන ඉහළම පෙළේ සුදුසුකම කුමක්ද?", "සංගීත නිපුන් (සහ විශාරද)", "ප්‍රාථමික සහතිකය පමණක්", "කෝලම් ශූරී", "හොරණෑ ප්‍රවීණ", "ප්‍රථමා, මධ්‍යමා, විශාරද හා නිපුන් ලෙස භාත්ඛණ්ඩේ විභාග මට්ටම් පවතී."),
        q("ශ්‍රී ලංකාවේ 'රංග කලා' හා සංගීත සංරක්ෂණය සඳහා 'කලා මණ්ඩලය' පිහිටුවීමෙන් අපේක්ෂා කළ අරමුණ කුමක්ද?", "ජාතික කලා ශිල්ප රැකගැනීම හා කලාකරුවන්ට අනුග්‍රහය දැක්වීම", "විදේශීය ගීත පමණක් ප්‍රචාරය කිරීම", "කලා උත්සව නතර කිරීම", "පැරණි පොත්පත් විකුණා දැමීම", "සංගීත, නර්තන හා නාට්‍ය අනුමණ්ඩල හරහා කලාකරුවන් ඇගයීම හා ග්‍රන්ථ ප්‍රකාශනය සිදුවේ."),
        q("ඉන්දියාවේ ජාතික සංගීතය හා සම්භාව්‍ය සංගීතය ප්‍රවර්ධනය කරන 'සංගීත නාටක ඇකඩමිය' (Sangeet Natak Akademi) පිහිටුවා ඇත්තේ කවර නගරයේද?", "නවදිල්ලි නගරයේ", "කොළඹ නගරයේ", "ලන්ඩන් නගරයේ", "කත්මණ්ඩු නගරයේ", "1952 දී ඉන්දියාවේ නවදිල්ලියේදී ප්‍රසාංගික කලා සඳහා ජාතික ඇකඩමිය පිහිටුවන ලදී."),
        q("පුරාණ ශ්‍රී ලංකාවේ කාන්තාවන් විසින් ගායනා හා වාදනය සිදු කළ බවට සාක්ෂි සපයන ඓතිහාසික මූලාශ්‍රයක් වන්නේ කුමක්ද?", "සීගිරි ගී, පූජාවලිය හා පොළොන්නරු සඳකඩපහණ කැටයම්", "20 වන සියවසේ පුවත්පත් පමණක්", "ඉංග්‍රීසි යටත් විජිත වාර්තා පමණක්", "ග්‍රැමෆෝන් නාමාවලි", "පැරණි සාහිත්‍යයේ හා විහාර කැටයම්වල කාන්තා වීණා වාදිකාවන් හා නළඟනන් දැක්වේ."),
        q("අනුරාධපුර යුගයේ සිටම ශ්‍රී ලංකාවේ වීණා වාදනය ප්‍රචලිතව පැවති බව සනාථ වන ප්‍රසිද්ධ කැටයම හමුවන්නේ කොහෙන්ද?", "ඉසුරුමුණිය හා තිවංක පිළිමගෙය / පොළොන්නරු කැටයම්", "ගාලු කොටු පවුර", "පැරණි ලන්දේසි රෝහල", "ත්‍රිකුණාමල වරාය", "අනුරාධපුර හා පොළොන්නරු පුරාවිද්‍යා ස්ථානවල වීණා හා බටනළා වයන රූප දක්නට ලැබේ."),
        q("'උමංදාව' සහ 'සද්ධර්මරත්නාවලිය' වැනි ගද්‍ය කෘතිවල පවා පංචතූර්ය නාදය ගැන සඳහන් වීමෙන් පැහැදිලි වන්නේ කුමක්ද?", "සංගීතය පුරාණ ශ්‍රී ලාංකේය ජන ජීවිතයේ අනිවාර්ය අංගයක් වූ බව", "එදා සංගීතය තහනම් කර තිබූ බව", "පංචතූර්ය භාණ්ඩ තිබුණේ ඉන්දියාවේ පමණක් බව", "බෙර වර්ග භාවිත නොකළ බව", "රාජ මාලිගා, පූජා සහ උත්සවවලදී පංචතූර්ය නාදය බහුලව භාවිත වූ බව සාහිත්‍යයෙන් පෙනේ."),
        q("භාරතීය හා ලාංකේය සංගීත ඉතිහාසයේ 'පණ්ඩිත්' (Pandit) සහ 'උස්තාද්' (Ustad) යන ගෞරව නාම භාවිත කරන්නේ කුමන පදනමකින්ද?", "හින්දු හා ඉස්ලාම් සංස්කෘතික සම්ප්‍රදායන්හි ප්‍රවීණ සංගීත විද්වතුන්ට", "ආරම්භක ශිෂ්‍යයන්ට පමණක්", "වාද්‍ය භාණ්ඩ වෙළෙන්දන්ට", "සංගීත ශාලා හිමියන්ට", "සංගීතයේ ප්‍රවීණත්වයට පත් හින්දු ගුරුවරුන්ට පණ්ඩිත් ලෙසද මුස්ලිම් ගුරුවරුන්ට උස්තාද් ලෙසද ගෞරව කෙරේ."),
        q("කාන්තා ප්‍රවීණ සංගීත ශිල්පිනියන්ට ගෞරව දැක්වීම සඳහා භාරතීය සම්ප්‍රදායේ යොදන නාමයන් මොනවාද?", "විදුෂී, පණ්ඩිතා හෝ බේගම්", "මුදලිඳු හෝ ආරච්චි", "කෝනංගි හෝ පොතේගුරු", "උස්තාද් හෝ ස්වාමි", "විදුෂී කිෂෝරි අමෝන්කර්, බේගම් අක්තාර්, විදුෂී එන්. රාජම් ආදී ලෙස ගෞරව නාම භාවිත කෙරේ."),
        q("'බේගම් අක්තාර්' (Begum Akhtar) ඉන්දියානු සංගීත ඉතිහාසයේ ප්‍රකට වන්නේ කුමන ගායන ශෛලීන් නිසාද?", "ගසල්, දාද්‍රා සහ ඨුම්රි ගායනය", "බටහිර පොප් ගායනය", "සිංහල වන්නම් ගායනය", "කෝලම් කවි ගායනය", "ගසල් රැජින (Mallika-e-Ghazal) ලෙස හැඳින්වුණු බේගම් අක්තාර් අර්ධ ශාස්ත්‍රීය සංගීතයේ අග්‍රගණ්‍ය විය."),
        q("භාරතීය ශාස්ත්‍රීය සංගීතයට ප්‍රථම වරට 'වයලීනය' වාද්‍ය භාණ්ඩයක් ලෙස යොදාගෙන එය ලොවට ගෙන ගිය කාන්තා ශිල්පිනියක කවුද?", "විදුෂී එන්. රාජම් (N. Rajam)", "රුක්මණී දේවි", "ලතා වල්පොල", "ඇනී බොතේජු", "ගායනා ශෛලියෙන් (Gayaki Ang) වයලීනය වාදනය කිරීමේ විශේෂඥවරියක ලෙස පද්ම භූෂණ එන්. රාජම් ප්‍රකටය."),
        q("ශ්‍රී ලංකාවේ සරල ගීතය 'මධ්‍යම පාන්තික හා බුද්ධිමත් රසික සමාජයට' ගෙන යාමේදී වැදගත් වූ සංගීතවේදියෙකු කවුද?", "පණ්ඩිත් අමරදේව සහ ප්‍රේමසිරි කේමදාස", "පිලිප්පු සිංඤෝ", "සී. දොන් බස්තියන්", "ජෝන් ද සිල්වා", "ප්‍රබුද්ධ කාව්‍යමය පද රචනා හා ගැඹුරු තනු යොදා ගැනීමෙන් මෙම පිරිස උසස් රසිකත්වයක් ගොඩනැගූහ."),
        q("භාරතීය සංගීතයේ 'රාගමාලා' (Ragamala) චිත්‍ර කලාව යනු කුමක්ද?", "රාගවල ස්වරූපය, කාලය හා රසය වර්ණවත් සිතුවම් මගින් නිරූපණය කිරීම", "වාද්‍ය භාණ්ඩ මත මල් ඇඳීම", "බෙර සම් වර්ණ ගැන්වීම", "වේදිකා තිර රෙදි මැසීම", "මධ්‍යකාලීන ඉන්දියාවේ එක් එක් රාගයේ පෞරුෂය හා හැඟීම් ක්ෂුද්‍ර සිතුවම් (Miniature paintings) ලෙස ඇඳිණි."),
        q("ශ්‍රී ලංකාවේ පළමු වරට සංගීතයෙන් 'ශ්‍රී ලංකාභිමාන්‍ය' ජාතික සම්මානයෙන් පිදුම් ලැබූ කලාකරුවා කවුද?", "පණ්ඩිත් ඩබ්ලිව්. ඩී. අමරදේව", "පිලිප්පු සිංඤෝ", "විශ්වනාත් ලෞජි", "ආර්. මුත්තුසාමි", "2007 වර්ෂයේදී ශ්‍රී ලංකාවේ ඉහළම සිවිල් ගෞරවය වන ශ්‍රී ලංකාභිමාන්‍ය සම්මානය අමරදේවයන්ට හිමිවිය."),
        q("මෙරට 'ශාස්ත්‍රීය නර්තනයට' හා වේදිකාවට අවශ්‍ය 'වන්නම් ගායනා' ස්වරලිපිගත කිරීමට ප්‍රමුඛ වූයේ කවුද?", "ඩබ්ලිව්. බී. මකුලොළුව සහ සී. ද එස්. කුලතිලක", "මියාන් තාන්සේන්", "අමීර් ඛුස්රෝ", "පණ්ඩිත් රවි ශංකර්", "දේශීය වන්නම් හා කවි නාද මාලා ලේඛනගත කර ආරක්ෂා කිරීමට එතුමන්ලා වෙහෙසුණහ."),
        q("උත්තර භාරතීය සංගීතයේ 'සංගීත රත්නාකරය' ග්‍රන්ථයේ සඳහන් වන පරිදි 'සංගීතය' යන වචනයට ඇතුළත් වන කලාංග තුන කුමක්ද?", "ගායනය (ගීත), වාදනය (වාද්‍ය) සහ නර්තනය (නෘත්‍ය)", "කවි, කතා සහ චිත්‍ර", "ව්‍යාකරණ, ගණිතය සහ තාරකා විද්‍යාව", "මූර්ති, කැටයම් සහ ගෘහ නිර්මාණ", "'ගීතං වාද්‍යං තථා නෘත්‍යං ත්‍රයං සංගීත මුච්‍යතේ' යනුවෙන් මෙම අංග තුනම සංගීතය ලෙස දැක්වේ."),
        q("බටහිර සංගීත ඉතිහාසයේ 'ප්‍රේමණීය යුගයේ' (Romantic Era) පියානෝ වාදන නිර්මාණකරුවෙකු ලෙස ප්‍රකට වන්නේ කවුද?", "ෆ්‍රෙඩ්රික් චොපින්", "භරතමුනි පඬිතුමා", "ශාර්ංගදේව පඬිතුමා", "මියාන් තාන්සේන්", "චොපින්, ෂූබර්ට් සහ චයිකොව්ස්කි ප්‍රේමණීය යුගයේ මහා සංගීතඥයෝ වෙති."),
        q("සිංහල ගීත කලාවේ 1960 ගණන්වල බිහිවූ 'ධර්මදාස වල්පොල', 'සිසිර සේනාරත්න' සහ 'ඉන්ද්‍රානි විජයබණ්ඩාර' වැනි ගායකයන් ප්‍රකට වන්නේ කුමකටද?", "යුග ගී හා සුමිහිරි සරල/චිත්‍රපට ගීත ගායනයට", "සොකරි නාට්‍ය අණබෙර ගැසීමට", "තම්මැට්ටම් වාදනයට", "කර්ණාටක ඝටම් වාදනයට", "ගයා ගීතා ගමේ වෙලේ, ඔලු මලේ සුදු සුදු වැනි සුමිහිරි යුග ගී හා සරල ගී එතුමන්ලා ගැයූහ."),
        q("දේශීය හා භාරතීය සංගීතයේ අනාගත පැවැත්ම සඳහා සංගීත ඉතිහාසය හැදෑරීමේ ප්‍රධාන ප්‍රතිලාභය කුමක්ද?", "සම්ප්‍රදාය හඳුනාගෙන නව නිර්මාණශීලී මංපෙත් විවර කර ගැනීම", "අතීත භාණ්ඩ සියල්ල කෞතුකාගාරවල සඟවා තැබීම", "නව තාක්ෂණය ප්‍රතික්ෂේප කිරීම", "ගායනා කිරීම නතර කර පොත් පමණක් කියවීම", "පැරණි මූලාශ්‍ර හා ශිල්පීන් අධ්‍යයනය කිරීමෙන් වඩාත් පරිපූර්ණ නිර්මාණ බිහි කළ හැකිය."),
        q("1939 දී පමණ ශ්‍රී ලංකාවේ 'චිත්‍රපට සංගීතයට' පෙර පැවති ප්‍රධානතම ජනප්‍රිය සංගීත මාධ්‍ය දෙක කුමක්ද?", "නූර්ති වේදිකාව සහ ග්‍රැමෆෝන් තැටි", "අන්තර්ජාලය සහ රූපවාහිනිය", "CD තැටි සහ MP3 ගොනු", "ටෙලිනාට්‍ය සහ ස්මාර්ට් ජංගම දුරකථන", "නිදහසට පෙර යුගයේ ජනතාව ගීත රසවින්දේ නූර්ති රඟහල, ග්‍රැමෆෝන් තැටි හා මුල් ගුවන්විදුලියෙනි."),
        q("දක්ෂිණ භාරතීය සංගීතයේ විශිෂ්ට මෘදංග වාදකයෙකු හා ශාස්ත්‍රීය කලාකරුවෙකු ලෙස හැඳින්වෙන්නේ කවුද?", "පාලඝාට් මණි අයියර්", "විශ්වනාත් ලෞජි", "ආනන්ද සමරකෝන්", "පිලිප්පු සිංඤෝ", "පාලඝාට් මණි අයියර් කර්ණාටක මෘදංග වාදනය ලොව ඉහළම තලයට ගෙන ගිය මහා කලාකරුවෙකි."),
        q("'සංගීත විශාරද' හා 'සංගීත නිපුන්' යන උපාධි ලබා මෙරට විශ්වවිද්‍යාල හා පාසල් සංගීත අධ්‍යාපනය ඔසවා තැබූ මහාචාර්යවරයෙකු කවුද?", "මහාචාර්ය සනත් නන්දසිරි", "පිලිප්පු සිංඤෝ", "සී. දොන් බස්තියන්", "ජෝන් ද සිල්වා", "මහාචාර්ය සනත් නන්දසිරි හා දයාරත්න රණතුංග විශ්වවිද්‍යාල සංගීත අධ්‍යාපනය දියුණු කළහ."),
        q("ගුවන්විදුලි 'ළමා පිටිය' හරහා ශ්‍රී ලංකාවේ අනාගත ගායක පරපුරට අත්වැලක් සැපයූ ප්‍රවීණ ගායිකාව හා නිවේදිකාව කවුද?", "විශාරද නන්දා මාලිනී", "බේගම් අක්තාර්", "කිෂෝරි අමෝන්කර්", "එම්. එස්. සුබ්බුලක්ෂ්මි", "රේඩියෝ සිලෝන් ළමා පිටිය අමරදේව, නන්දා මාලිනී, වික්ටර් රත්නායක ආදී බොහෝ දෙනාට තෝතැන්නක් විය."),
        q("'වසන්තයේ මල් කැකුළු' හා දේශීය ළමා ගී සංග්‍රහය නිර්මාණය කිරීමෙන් ළමා සංගීතය පෝෂණය කළේ කවුද?", "ආනන්ද සමරකෝන්, සුනිල් ශාන්ත සහ කලාකරුවන්", "මියාන් තාන්සේන්", "අමීර් ඛුස්රෝ", "වෙන්කටමුඛී", "ළමා මනසට ගැළපෙන සරල රිද්ම හා නිවැරදි සිංහල වදන් සහිත ළමා ගී රැසක් එදා බිහිවිය."),
        q("ශ්‍රී ලංකාවේ පළමු වරට බටහිර වාද්‍ය භාණ්ඩ හා සිංහල සංගීතය සමඟ 'ශ්‍රී ලංකා ගුවන්විදුලි වාද්‍ය වෘන්දය' ශක්තිමත් කළේ කවර යුගයේදීද?", "1950 - 1970 දශකවල", "1815 - 1830 දශකවල", "1700 - 1720 දශකවල", "1505 - 1550 දශකවල", "නිදහසින් පසු දශක දෙක ගුවන්විදුලි සංගීතයේ ස්වර්ණමය යුගය ලෙස සැලකේ."),
        q("ඉන්දීය සංගීතයේ 'කල්‍යාණ්, බිලාවල්, ඛමාජ්' ආදී ථාට දහය වර්තමානයේ පිළිගැනෙන පද්ධතිය බවට පත්වූයේ කාගේ කාලයේද?", "20 වන සියවසේ පණ්ඩිත් භාත්ඛණ්ඩේගේ කාලයේ", "ක්‍රි.පූ. 5 වන සියවසේ", "10 වන සියවසේ", "15 වන සියවසේ", "පණ්ඩිත් භාත්ඛණ්ඩේ මුල් මේල රැස අතරින් ප්‍රායෝගිකව වඩාත් සුදුසු ථාට 10 තෝරා සකස් කළේය."),
        q("ශාර්ංගදේවගේ 'සංගීත රත්නාකරය' ග්‍රන්ථයේ අඩංගු වන මුළු අධ්‍යාය ගණන කීයද (සප්තාධ්‍යායී)?", "7 කි", "3 කි", "12 කි", "22 කි", "ස්වර, රාග, ප්‍රකීර්ණක, ප්‍රබන්ධ, තාල, වාද්‍ය සහ නෘත්‍ය යන අධ්‍යාය 7 නිසා එය සප්තාධ්‍යායී නම් වේ."),
        q("මධ්‍යකාලීන භාරතීය සංගීතයේ දී අතිශය ජනප්‍රිය වූ 'ටප්පා' (Tappa) ගායන ශෛලිය හඳුන්වා දුන්නේ කවුද?", "ෂෝරි මියාන් (Shori Miyan)", "මියාන් තාන්සේන්", "භරතමුනි", "ආනන්ද සමරකෝන්", "පංජාබයේ ඔටු සාරථීන්ගේ ජන ගී ආශ්‍රයෙන් ලක්නව්හි ෂෝරි මියාන් ටප්පා ශෛලිය සැකසීය."),
        q("සිංහල ගීත කලාවේ මුල් පෙළේ 'පෙරදිග රාගාශ්‍රිත ගීත' හා 'ගැමි කවි' එක්කළ සංගීතඥ 'ජයතිස්ස අලහකෝන්' හෝ 'මර්වින් පෙරේරා' වැන්නන් ප්‍රකට වන්නේ කුමකටද?", "මිහිරි භාවපූර්ණ සරල ගී නිර්මාණයට", "තම්මැට්ටම් වාදනයට", "සොකරි රඟපෑමට", "නාඩගම් පොත් මුද්‍රණයට", "'මේ නගරය', 'ආදරයේ උල්පත වූ අම්මා' වැනි ගීත තුළින් මෙරට සරල ගීය පෝෂණය විය."),
        q("දක්ෂිණ භාරතීය හා උත්තර භාරතීය සංගීතඥයන් අතර එකිනෙකාගේ රාග හුවමාරු කරගැනීම (Jugalbandi) මගින් ලැබෙන ප්‍රතිඵලය කුමක්ද?", "පද්ධති දෙකෙහිම සෞන්දර්යය එකම වේදිකාවකින් රසවිඳීමට ලැබීම", "සංගීතය සම්පූර්ණයෙන් නතර වීම", "ස්වර සප්තකය අහෝසි වීම", "වාද්‍ය භාණ්ඩ කැඩී යාම", "හින්දුස්ථානි හා කර්ණාටක ශිල්පීන්ගේ ජුගල්බන්දි ප්‍රසංග ඉන්දීය සංගීතයේ සමගිය පෙන්වයි."),
        q("'සංගීතය මිනිස් සමාජයේ විශ්ව භාෂාවක්' ලෙස හඳුන්වනු ලබන්නේ කුමක් නිසාද?", "භාෂා භේදයකින් තොරව ඕනෑම අයෙකුට හැඟීම් හා රසය දැනෙන බැවිනි", "සියලු රටවල එකම අකුරු තිබෙන බැවිනි", "එය ඉගෙනීමට පොත් අවශ්‍ය නොවන බැවිනි", "එකම වාද්‍ය භාණ්ඩයක් පමණක් ඇති බැවිනි", "නාදය හා රිද්මය මනුෂ්‍ය හදවතට ඍජුවම ආමන්ත්‍රණය කරන විශ්වීය මාධ්‍යයකි."),
        q("පුරාණ ශ්‍රී ලංකාවේ රජ දරුවන් සංගීතඥයන්ට හා නළුවන්ට ගම්වර ප්‍රදානය කර ඇති බව පැවසෙන්නේ කුමක් උදෙසාද?", "කලා ශිල්පීන්ගේ ජීවනෝපාය සුරක්ෂිත කර කලාව රැකගැනීමට", "යුද්ධයට පමණක් යැවීමට", "සංගීතය නැවැත්වීමට", "විදේශිකයන්ට විකිණීමට", "විහාරස්ථාන හා රාජ සභා ආශ්‍රිත කලාකරුවන් රැකගැනීමට පැරණි රජවරු නින්දගම් දුන්හ."),
        q("'සංගීත අධ්‍යාපනය' පාසල් සිසුවෙකුගේ පෞරුෂ වර්ධනයට උපකාරී වන ප්‍රධාන ආකාරය කුමක්ද?", "සංවේදී බව, විනය, සාමූහිකත්වය හා නිර්මාණශීලීත්වය වැඩි කිරීම", "ශාරීරික වෙහෙස පමණක් ඇති කිරීම", "අනෙක් විෂයන් අමතක කරවීම", "හුදෙක් තරඟකාරීත්වය ඇති කිරීම", "සංගීතය මගින් සිසුන්ගේ මානසික සමබරතාව, ශ්‍රවණ කුසලතා හා රසඥතාව පෝෂණය වේ."),
        q("ලංකාවේ 'ගීත සාහිත්‍යය' පිළිබඳ හැදෑරීමේදී 1956 පරපුර හෙවත් පේරාදෙණිය සාහිත්‍ය-කලා ප්‍රබෝධය ඉටු කළ කාර්යය කුමක්ද?", "දේශීය මූලයන් ගවේෂණය කර නවීන නිර්මාණ බිහිකිරීම", "සියලු ජන කවි විනාශ කිරීම", "පාර්සි නාට්‍ය පමණක් පෙන්වීම", "සංගීතයෙන් වචන ඉවත් කිරීම", "මහාචාර්ය සරච්චන්ද්‍ර ආදීන්ගේ නායකත්වයෙන් නාට්‍ය, ගීත හා සාහිත්‍යයේ නව පුනරුදයක් ඇතිවිය."),
        q("අතීතයේ සිට වර්තමානය දක්වා විකාශනය වූ ශ්‍රී ලාංකේය සංගීතය හැදෑරීමේදී දැකිය හැකි ප්‍රධාන ලක්ෂණය කුමක්ද?", "දේශීය උරුමය රැකගනිමින් විවිධ සංස්කෘතික ආභාස උකහා ගැනීම", "සම්පූර්ණයෙන් එකම තැන පල්වීම", "වෙනත් කිසිදු රටකින් ආභාසයක් නොලැබීම", "ජන ගී සම්පූර්ණයෙන් අතුරුදහන් වීම", "ජන ගී පදනම මත භාරතීය හා බටහිර ආභාස මුසු කරමින් සිංහල සංගීතය විකාශනය වී ඇත.")
    )
}
